/** Orders the drawn items into steps and gives each a start time. */
function schedule(items, doc) {
	items.sort((a, b) => a.step - b.step || a.rank - b.rank);
	const firstStep = Math.min(...items.filter((i) => i.step >= 1).map((i) => i.step), 1);
	for (const it of items) if (it.step >= 0 && it.step < firstStep) it.step = firstStep;
	const stepIndices = Array.from(new Set(items.filter((i) => i.step >= 0).map((i) => i.step))).sort((a, b) => a - b);
	const steps = [];
	let t = 0;
	let k = 0;
	if (items.length && items[0].step < 0) {
		items[0].start = 0;
		t = items[0].dur * .85;
		k = 1;
	}
	for (const s of stepIndices) {
		const start = t;
		let end = t;
		while (k < items.length && items[k].step === s) {
			items[k].start = t;
			end = Math.max(end, t + items[k].dur);
			t += items[k].dur * .78;
			k++;
		}
		t = end + .3;
		steps.push({
			index: s,
			caption: doc.steps.find((d) => d.index === s)?.caption,
			start,
			end
		});
	}
	return {
		steps,
		duration: items.reduce((m, i) => Math.max(m, i.start + i.dur), 0)
	};
}
// src/core/draw/title.ts
function drawTitle(ctx) {
	const { doc, textStyle, lay, defs, rc, rand, base, mark, uid, add, content } = ctx;
	if (doc.title) {
		const g = el("g", { class: "title" }, content);
		const tp = lay.fontPx * 1.55;
		const { w } = measure(doc.title, tp, lay.family, Math.min(700, lay.weight + 200));
		const cx = lay.width / 2;
		const cy = 22 + tp / 2;
		const pieces = handText(g, doc.title, cx, cy, {
			...textStyle,
			px: tp,
			weight: Math.min(700, lay.weight + 200)
		}, rand, defs, uid);
		const y = cy + tp * .62;
		const ul = rc.curve([
			[cx - w / 2 - 6, y + 2],
			[cx, y - 1 + (rand() - .5) * 3],
			[cx + w / 2 + 10, y - 3]
		], base("title-ul", {
			stroke: mark,
			strokeWidth: 2,
			roughness: .6,
			disableMultiStroke: true
		}));
		g.appendChild(ul);
		add(-1, 0, [...pieces, ...piecesFrom(ul, mark)], .9);
	}
}
